+//!    表项也不污染既有表项的 EMA；
+//! 3. 非法配置被 `set_config` 整体拒收（warn + 保留旧配置），合法新配置照常生效；
+//! 4. 合法输入的既有语义不变（守卫不误伤热路径）。
+//!
+//! 同步、无 tokio：`MemoryHealthTable` 全部状态都在内存 Mutex 里，时钟注入
+//! `with_config_and_clock` 固定，与既有 health_* 测试口径一致。
+
+use dispatch::health::{
+    AttemptReport, FailureClass, HealthSetting, HealthTable, MemoryHealthTable, TpsSample,
+};
+
+/// 固定时钟的纯内存健康表（`now_ms` 恒 1_000_000）。
+fn table() -> MemoryHealthTable {
+    let now = 1_000_000u64;
+    MemoryHealthTable::with_config_and_clock(HealthSetting::default(), move || now)
+}
+
+/// 空 unit_key 的 `record` / `record_tps` 一律丢弃：表保持为空。
+///
+/// 哪种 bug 会让它红：守卫缺失或写在建表项之后 —— `""` 变成一条真实表项，
+/// `entries()` 非空（admin 读出面凭空多出一个空键渠道），或 `record("")`
+/// 在锁内/构造器处 panic。
+#[test]
+fn empty_unit_key_is_dropped() {
+    let t = table();
+
+    // 带延迟与 tps 的完整载荷：守卫应发生在任何记账 / digest 双写之前。
+    t.record(
+        "",
+        AttemptReport::new(Ok(200), Some(42), None).with_tps(TpsSample::Measured(100.0)),
+    );
+    t.record(
+        "",
+        AttemptReport::new(Err(FailureClass::Retryable), None, None),
+    );
+    t.record_tps("", TpsSample::Measured(100.0));
+    t.record_tps("", TpsSample::Estimated(50.0));
+
+    assert!(
+        t.entries().is_empty(),
+        "空 unit_key 不得建表项，entries 应为空"
+    );
+    // 读侧兜底：get("") 拿到的仍是默认满健康态（表里根本没这条记录）。
+    assert_eq!(t.get("").request_count, 0, "空键不得被记账");
+}
+
+/// 非物理吞吐样本（NaN / Inf / ≤0）被丢弃：先不建表项，再不污染既有 EMA。
+///
+/// 哪种 bug 会让它红：样本校验缺失 / 写在 `states.insert` 之后 —— 坏样本
+/// 建出空键表项，或把 NaN / 负值并入 `tps_ema`（首样本直取路径 → ema=NaN，
+/// 之后所有比较全废，选择器读到 NaN 权重）。
+#[test]
+fn non_physical_tps_samples_are_dropped() {
+    let t = table();
+    let key = "ch-1/gpt-4o";
+
+    t.record_tps(key, TpsSample::Measured(f64::NAN));
+    t.record_tps(key, TpsSample::Estimated(f64::INFINITY));
+    t.record_tps(key, TpsSample::Measured(-1.0));
+    t.record_tps(key, TpsSample::Estimated(0.0));
+    assert!(
+        t.entries().is_empty(),
+        "坏样本不得创建表项（校验须在建表项之前）"
+    );
+
+    // 合法样本正常建立基线：首样本直取 → 100.0。
+    t.record_tps(key, TpsSample::Measured(100.0));
+    assert_eq!(t.get(key).tps_ema, 100.0, "合法样本应成为 EMA 基线");
+
+    // 基线建立后再喂坏样本：EMA 必须原封不动。
+    t.record_tps(key, TpsSample::Measured(f64::NAN));
+    assert_eq!(t.get(key).tps_ema, 100.0, "NaN 样本不得污染既有 EMA");
+
+    // record 顺路带入的 tps 走同一道守卫。
+    t.record(
+        key,
+        AttemptReport::new(Ok(200), None, None).with_tps(TpsSample::Measured(f64::INFINITY)),
+    );
+    assert_eq!(
+        t.get(key).tps_ema,
+        100.0,
+        "report.tps 的非物理样本同样在入库边界丢弃"
+    );
+}
+
+/// `set_config` 非法配置整体拒收并保留旧配置；合法新配置照常生效。
+///
+/// 哪种 bug 会让它红：校验缺失或写成"部分应用" —— 坏值直接进配置槽
+/// （α=NaN 让 EWMA 全表变 NaN；base > max 让冷却时长公式退化），或旧配置
+/// 被清空/半写，读出的 `get_config()` 不等于拒绝前的值。
+#[test]
+fn invalid_setting_keeps_old_config() {
+    let t = table();
+    let before = t.get_config();
+
+    // α = NaN：非有限值直接染黑整个 EWMA。
+    t.set_config(HealthSetting {
+        alpha: f64::NAN,
+        ..before
+    });
+    assert_eq!(
+        t.get_config(),
+        before,
+        "alpha=NaN 应被拒收且逐字段保留旧配置"
+    );
+
+    // base 超过天花板：阶梯起点高于上限，时长公式退化。
+    t.set_config(HealthSetting {
+        cooldown_base_ms: 9_000,
+        cooldown_max_ms: 3_000,
+        ..before
+    });
+    assert_eq!(
+        t.get_config(),
+        before,
+        "cooldown_base_ms > cooldown_max_ms 应被拒收且逐字段保留旧配置"
+    );
+
+    // 合法新配置照常生效（校验不误伤热更）。
+    t.set_config(HealthSetting {
+        cooldown_max_ms: 16_000,
+        ..t.get_config()
+    });
+    assert_eq!(t.get_config().cooldown_max_ms, 16_000, "合法新配置应生效");
+}
+
+/// 合法输入的既有语义不变：成功可被选中，单次传输层失败即冷却。
+///
+/// 哪种 bug 会让它红：守卫范围过宽（例如误按"载荷里带 tps"或"键里含 /"
+/// 丢弃），把合法上报一并吃掉 —— 渠道永远满血、失败永不进冷却。
+#[test]
+fn valid_behavior_unchanged() {
+    let t = table();
+    let now_ms = 1_000_000u64;
+    let key = "ch-2/gpt-4o";
+
+    t.record(key, AttemptReport::new(Ok(200), Some(40), None));
+    assert!(t.is_selectable(key, now_ms), "成功上报后渠道应可被选择");
+
+    t.record(
+        key,
+        AttemptReport::new(Err(FailureClass::Retryable), None, None),
+    );
+    assert!(
+        !t.is_selectable(key, now_ms),
+        "单次传输层失败即进冷却（现有语义，守卫不得误伤）"
+    );
+}
