--- /dev/null
+++ b/.github/workflows/screen.yml
@@ -0,0 +1,73 @@
+name: screen
+
+# CI-side screening: evaluates the pending-state queue exported locally
+# (`screen.py --export-pending data/pending.jsonl`) against a CPU
+# laya-serve on the runner and commits the cache fragment back.
+# Local merge: `screen.py --merge-fragment data/cache-fragment.json`.
+
+on:
+  workflow_dispatch:
+    inputs:
+      pending:
+        description: pending queue file (JSONL)
+        default: data/pending.jsonl
+
+permissions:
+  contents: write
+
+jobs:
+  screen:
+    runs-on: ubuntu-latest
+    timeout-minutes: 300
+    env:
+      LAYA_API_KEY: laya-local
+      LAYA_PRELOAD: "1"
+      HF_HUB_DISABLE_XET: "1"
+    steps:
+      - uses: actions/checkout@v4
+
+      - uses: actions/setup-python@v5
+        with:
+          python-version: "3.12"
+          cache: pip
+
+      - name: Cache laya checkpoints
+        uses: actions/cache@v4
+        with:
+          path: ~/.cache/huggingface
+          key: hf-laya-0.4.6
+
+      - name: Install laya (CPU)
+        run: |
+          python -m pip install --upgrade pip
+          pip install torch==2.6.0 --index-url https://download.pytorch.org/whl/cpu
+          pip install "transformers==5.19.0" "laya[serve]==0.4.6"
+
+      - name: Start laya-serve
+        run: |
+          nohup python scripts/serve_cpu.py > /tmp/laya.log 2>&1 &
+          for i in $(seq 1 90); do
+            curl -sf http://127.0.0.1:8000/health > /dev/null && break
+            sleep 10
+          done
+          curl -sf http://127.0.0.1:8000/health | head -c 300
+          echo
+          tail -5 /tmp/laya.log
+
+      - name: Evaluate pending
+        run: |
+          python scripts/eval_pending.py \
+            --pending "${{ inputs.pending }}" \
+            --out data/cache-fragment.json
+
+      - name: Commit fragment
+        run: |
+          git config user.name "screen-bot"
+          git config user.email "screen-bot@users.noreply.github.com"
+          git add data/cache-fragment.json
+          if git diff --cached --quiet; then
+            echo "no changes to commit"
+          else
+            git commit -m "data: cache fragment from CI run ${{ github.run_id }}"
+            git push
+          fi
